   105→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   106→        });
   107→      }
   108→
   109→      productId = config.topup_dodo_product_id;
   110→      amount = Math.round(topupNum * 100); // cents
   111→      itemName = `Wallet Top-Up $${topupNum}`;
   112→      itemType = "topup";
   113→    } else {
   114→      // ─── PLAN SUBSCRIPTION FLOW (unchanged) ───
   115→      const { data: plan, error } = await supabase
   116→        .from("plans")
   117→        .select("*")
   118→        .eq("id", plan_id)
   119→        .eq("active", true)
   120→        .single();
   121→      if (error || !plan) {
   122→        return new Response(JSON.stringify({ error: "Plan not found or inactive" }), {
   123→          status: 404, headers: { ...corsHeaders, "Content-Type": "application/json" },
   124→        });
   125→      }
   126→      if (!plan.dodo_product_id) {
   127→        return new Response(JSON.stringify({ error: "This plan is not configured for Dodo Payments. Add a Dodo Product ID in admin." }), {
   128→          status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" },
   129→        });
   130→      }
   131→      productId = plan.dodo_product_id;
   132→      amount = Math.round(plan.price * 100);
   133→      credits = plan.credits;
   134→      itemName = plan.name;
   135→      itemType = "plan";
   136→      itemId = String(plan_id);
   137→    }
   138→
   139→    // Build return URL
   140→    const baseReturnUrl =
   141→      (typeof return_url === "string" && return_url) ||
   142→      `${req.headers.get("origin") || "https://rankora.co"}/payment/callback`;
   143→
   144→    // 1) Create local payment record
   145→    const insertPayload: any = {
   146→      user_id: user.id,
   147→      amount,
   148→      currency,
   149→      credits_purchased: credits,
   150→      status: "created",
   151→      payment_gateway: "dodo",
   152→    };
   153→    if (itemType === "plan" && itemId) {
   154→      insertPayload.plan_id = itemId;
   155→    }
   156→
   157→    const insertRes = await supabase
   158→      .from("payments")
   159→      .insert(insertPayload)
   160→      .select("id")
   161→      .single();
   162→
   163→    if (insertRes.error || !insertRes.data) {
   164→      console.error("Failed to create local payment record:", insertRes.error?.message);
   165→      return new Response(JSON.stringify({ error: "Failed to create local payment record" }), {
   166→        status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" },
   167→      });
   168→    }
   169→
   170→    const localPaymentId = insertRes.data.id as string;
   171→    const returnUrlWithLocalPaymentId = `${baseReturnUrl}${baseReturnUrl.includes("?") ? "&" : "?"}local_payment_id=${encodeURIComponent(localPaymentId)}`;
   172→
   173→    // 2) Create Dodo Checkout Session
   174→    const isLive = DODO_ENV === "live_mode";
   175→    const client = new DodoPayments({
   176→      bearerToken: DODO_API_KEY,
   177→      baseURL: isLive
   178→        ? "https://live.dodopayments.com"
   179→        : "https://test.dodopayments.com",
   180→    });
   181→
   182→    const cartItem: any = { product_id: productId, quantity: 1 };
   183→    if (itemType === "topup") {
   184→      cartItem.amount = amount; // dynamic amount in cents for PWYW product
   185→    }
   186→
   187→    const session = await client.checkoutSessions.create({
   188→      product_cart: [cartItem],
   189→      customer: {
   190→        email: user.email ?? "",
   191→        name: user.email?.split("@")[0] || "Customer",
   192→      },
   193→      billing_address: {
   194→        street: "NA",
   195→        city: "NA",
   196→        state: "NA",
   197→        country: "US",
   198→        zipcode: "00000",
   199→      },
   200→      return_url: returnUrlWithLocalPaymentId,
   201→      metadata: {
   202→        local_payment_id: localPaymentId,
   203→        user_id: user.id,
   204→        item_type: itemType,
   205→        item_id: itemId || "",
   206→        item_name: itemName,
   207→        credits: String(credits),
   208→      } as Record<string, string>,
   209→    });
   210→
   211→    // 3) Persist the Dodo checkout session id
   212→    if ((session as Record<string, unknown>).session_id) {
   213→      await supabase
   214→        .from("payments")
   215→        .update({ dodo_checkout_session_id: (session as Record<string, string>).session_id })
   216→        .eq("id", localPaymentId);
   217→    }
   218→
   219→    return new Response(
   220→      JSON.stringify({
   221→        checkout_url: (session as Record<string, string>).checkout_url,
   222→        checkout_session_id: (session as Record<string, string>).session_id,
   223→        payment_id: localPaymentId,
   224→      }),
   225→      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
   226→    );
   227→  } catch (err: unknown) {
   228→    console.error("create-dodo-checkout error:", err);
   229→    return new Response(
   230→      JSON.stringify({ error: err instanceof Error ? err.message : String(err) }),
   231→      { status: 500, headers: { ...corsHeaders, "Content-Type": "application/json" } },
   232→    );
   233→  }
   234→});
